let worldReady=false,pendingBattle=false,lastLevel=0;
function send(command,extra={}){if(frame.contentWindow)frame.contentWindow.postMessage({vkCommand:command,...extra},'*');}
function initialize(){if(!worldReady)return;send('initialize',{mapId:data.vkMapId,sex:data.heroSex||'male',style:data.heroStyle,level:data.zone||1,x:data.vkWorldX,y:data.vkWorldY,fromTop:!!data.vkWorldFromTop,cleared:!!data.clearedZones?.[data.zone]});}
frame.addEventListener('load',()=>{worldReady=true;initialize()});
window.addEventListener('message',e=>{if(e.source!==frame.contentWindow||!e.data||!e.data.vkWorld)return;const m=e.data;
 if(m.vkWorld==='position'||m.vkWorld==='ready'){
  if(m.level!==data.zone){data.zone=m.level;data.trainerCleared=!!(data.clearedZones||{})[m.level];data.vkWorldX=null;data.vkWorldY=null;data.vkWorldFromTop=false;}
  if(!m.interior&&Number.isFinite(m.x)&&Number.isFinite(m.y)){data.vkWorldX=m.x;data.vkWorldY=m.y;}
  if(m.vkWorld==='position'){data.steps=(data.steps||0)+1;try{if(window.VaelkorWildlands?.available)window.VaelkorWildlands.persistPosition();else vkPersistUnified()}catch(err){};const st=document.getElementById('steps');if(st)st.textContent='👣 '+data.steps+' Schritte';}
  const zl=document.getElementById('zoneLabel');if(zl)zl.textContent=vkRegionForZone(data.zone).label+' · '+(data.zone===1||data.zone%10===0?'Ort / Arena':'Abschnitt '+data.zone);
 }
 if(m.vkWorld==='encounter'||m.vkWorld==='guardian'){
  if(pendingBattle||battle)return;
  pendingBattle=true;
  try{if(m.vkWorld==='guardian')startTrainer();else startBattle();}catch(err){console.error('Weltkampf konnte nicht starten:',err);pendingBattle=false;send('battleEnd',{won:false});return;}
  let hadBattle=!!battle,wasGuardian=m.vkWorld==='guardian';
  const timer=setInterval(()=>{hadBattle=hadBattle||!!battle;if(!battle&&hadBattle){clearInterval(timer);pendingBattle=false;send('battleEnd',{won:wasGuardian&&!!data.trainerCleared});}},180);
  setTimeout(()=>{if(!hadBattle){clearInterval(timer);pendingBattle=false;send('battleEnd',{won:false});}},1200);
 }
 if(m.vkWorld==='interact'){
  if(m.kind==='expansion'){gameNotice(String(m.message||'Grünwald'));}
  else if(m.kind==='heal'){document.getElementById('healbutton')?.click();}
  else if(m.kind==='shop'){try{show('shop')}catch(err){gameNotice('Krämer geöffnet.')}}
  else if(m.kind==='forge')gameNotice('Schmiede: Die Werkstatt ist geöffnet.');
  else if(m.kind==='church')gameNotice('Kirche: Willkommen in Grünwald.');
  else gameNotice('Willkommen in Grünwald!');
 }
});
const gender=document.getElementById('vkGenderOverlay'),starter=document.getElementById('starteroverlay');
function checkGender(){if(!data.team||data.team.length===0){starter.classList.add('hidden');gender.classList.remove('show')}else{gender.classList.remove('show');if(!data.heroSex)data.heroSex='male';}}
document.querySelectorAll('[data-vk-gender]').forEach(b=>b.addEventListener('click',()=>{data.heroSex=b.dataset.vkGender;gender.classList.remove('show');starter.classList.add('hidden');window.vkChooseAppearance87(data.heroSex);send('sex',{sex:data.heroSex});}));
// Starter selection still uses the original game code, with its original cards, saves and tutorial.
